nta.declaration:
const int n = 6;
clock total_time;

int[0,20] grid[n][n];

bool canMove(int id, int x, int y, int dx, int dy, int len, bool horiz) {
    if (horiz) {
        int nextX = (dx > 0) ? x + len : x - 1;
        return nextX >= 0 && nextX < n && grid[y][nextX] == 0;
    } else {
        int nextY = (dy > 0) ? y + len : y - 1;
        return nextY >= 0 && nextY < n && grid[nextY][x] == 0;
    }
}

void place_car(int id, int len, int x, int y, bool horiz) {
    int i;
    for (i = 0; i < len; i++) {
        if (horiz && x + i < n) grid[y][x + i] = id;
        else if (!horiz && y + i < n) grid[y + i][x] = id;
    }
}

void move_car(int id, int x, int y, int dx, int dy, int len, bool horiz) {
    if (horiz) {
        if (dx > 0 && x+len < n)   { grid[y][x] = 0;      grid[y][x+len] = id;   }
        else if (dx < 0 && x-1 >= 0) { grid[y][x+len-1] = 0; grid[y][x-1] = id;  }
    } else {
        if (dy > 0 && y+len < n)   { grid[y][x] = 0;      grid[y+len][x] = id;   }
        else if (dy < 0 && y-1 >= 0) { grid[y+len-1][x] = 0; grid[y-1][x] = id;  }
    }
}

nta.system:
Init = initializer();
red       = horizontalCar(1,  2, 3, 2);
green     = horizontalCar(2,  2, 0, 0);
orange    = horizontalCar(3,  2, 2, 0);
blue      = verticalCar  (4,  2, 4, 0);
pink      = verticalCar  (5,  2, 2, 1);
yellow    = verticalCar  (6,  3, 5, 1);
purple    = verticalCar  (7,  2, 1, 2);
magenta   = verticalCar  (8,  3, 0, 3);
darkgreen = horizontalCar(9,  2, 3, 3);
gray      = verticalCar  (10, 2, 3, 4);
beige     = horizontalCar(11, 2, 4, 4);
brown     = horizontalCar(12, 2, 1, 5);
black     = horizontalCar(13, 2, 4, 5);

system Init, red, green, orange, blue, pink, yellow,
       purple, magenta, darkgreen, gray, beige, brown, black;
